begin;
create extension if not exists pgtap with schema extensions;
set local search_path = extensions, public;
select plan(16);
select is(pcm.sso_vencimento_ciclo_calendario('2024-01-31', 1, 'meses', 1), '2024-02-29'::date, 'fevereiro bissexto usa último dia');
select is(pcm.sso_vencimento_ciclo_calendario('2024-01-31', 1, 'meses', 2), '2024-03-31'::date, 'março retorna ao dia original');
select is(pcm.sso_vencimento_ciclo_calendario('2024-02-29', 1, 'anos', 4), '2028-02-29'::date, 'ano bissexto recupera âncora');
select is(pcm.sso_vencimento_ciclo_calendario('2026-10-01', 2, 'semanas', 1), '2026-10-15'::date, 'semanas respeitam intervalo');
select is(pcm.sso_vencimento_ciclo_calendario('2026-10-01', 3, 'dias', 2), '2026-10-07'::date, 'dias respeitam ciclo');
select is(pcm.sso_vencimento_ciclo_calendario('2026-10-01', 3, 'meses', 0), '2026-10-01'::date, 'ciclo zero é âncora');
select is(pcm.sso_vencimento_ciclo_calendario('2026-11-30', 3, 'meses', 1), '2027-02-28'::date, 'trimestre cruza ano e ajusta fevereiro à âncora');
select is(pcm.sso_vencimento_ciclo_calendario('2026-11-30', 3, 'meses', 2), '2027-05-30'::date, 'trimestre seguinte recupera dia original após fevereiro');
select throws_ok($$ select pcm.sso_vencimento_ciclo_calendario('2026-01-01', 0, 'dias', 1) $$, '22023', null, 'intervalo deve ser positivo');
select throws_ok($$ select pcm.sso_vencimento_ciclo_calendario('2026-01-01', 1, 'dias', -1) $$, '22023', null, 'ciclo não pode ser negativo');
select throws_ok($$ select pcm.sso_vencimento_ciclo_calendario('2026-01-01', 1, 'visita', 1) $$, '22023', null, 'modo visita não é unidade de calendário');
select throws_ok($$ select pcm.sso_vencimento_ciclo_calendario(null, 1, 'dias', 1) $$, '22023', null, 'data base é obrigatória');
select throws_ok($$ select pcm.sso_vencimento_ciclo_calendario('2026-01-01', 2147483647, 'anos', 2147483647) $$, '22023', null, 'overflow é rejeitado');
select is(pcm.sso_vencimento_ciclo_calendario('2096-02-29', 1, 'anos', 4), '2100-02-28'::date, 'século não bissexto usa último dia');
select throws_ok($$ select pcm.sso_vencimento_ciclo_calendario('9999-12-31', 1, 'dias', 1) $$, '22023', null, 'datas além do limite são rejeitadas');
select ok(not has_function_privilege('authenticated', 'pcm.sso_vencimento_ciclo_calendario(date,integer,text,integer)', 'execute'), 'função interna não é exposta a usuário autenticado');
select * from finish();
rollback;
